// Mode: Run Once for Each Item. One Gemini response in, one parsed object out.
// Checks FORMAT only (is it a JSON object?). Validate checks CONTENT.
const candidate = $json.candidates?.[0];
const raw = candidate?.content?.parts?.[0]?.text;

function tryParse(s) {
  try {
    const v = JSON.parse(s);
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch (e) {
    return null;
  }
}

let parsed = null;
if (raw && typeof raw === 'object') {
  parsed = raw; // JSON mode may already give an object
} else if (typeof raw === 'string') {
  // Strip markdown code fences: ```json ... ```
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  parsed = tryParse(cleaned);
  if (!parsed) {
    // Last resort: the first {...} block inside surrounding prose
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) parsed = tryParse(match[0]);
  }
}

if (!parsed) {
  const reason = candidate?.finishReason;
  const apiError = $json.error ? String($json.error.message || $json.error).slice(0, 200) : null;
  parsed = {
    category: "Unclear",
    confidence_note: apiError
      ? `Gemini call failed after retries: ${apiError}`
      : "Failed to parse LLM output as JSON" + (reason && reason !== "STOP" ? ` (finishReason: ${reason})` : "")
  };
}
return { json: parsed };

// Mode: Run Once for Each Item.
const llmOutput = { ...$json };
// The email this Gemini result belongs to (paired item, not the first email of the poll).
let emailData;
try {
  emailData = $('Reduce Noise').item.json;
} catch (e) {
  // Fallback if paired-item info is lost: Gemini returns exactly one item per input, in order.
  emailData = $('Reduce Noise').all()[$itemIndex].json;
}

const subject = String(emailData["Subject"] || "");
const body = String(emailData["Email Body"] || "");
const sender = String(emailData["Sender Email"] || "").toLowerCase();

const ALLOWED_CATEGORIES = [
  "Automation Inquiry",
  "Reporting/Data Inquiry",
  "Pricing Question",
  "Support/Follow-up",
  "Spam/Irrelevant",
  "Unclear"
];
const ALLOWED_URGENCY = ["low", "medium", "high", "not_stated"];

const reasons = [];   // every reason this email needs a human, not just the first

// Guardrail 1: category must be one of the allowed 6
if (!ALLOWED_CATEGORIES.includes(llmOutput.category)) {
  reasons.push(`Invalid category returned: "${llmOutput.category}"`);
  llmOutput.category = "Unclear";
}

// Guardrail 2: category itself was Unclear
if (llmOutput.category === "Unclear") {
  reasons.push(llmOutput.confidence_note || "Classified as Unclear: too vague or ambiguous to fit a category.");
}

// Guardrail 3: required fields missing or urgency outside the allowed values
if (!llmOutput.summary || !llmOutput.urgency) {
  reasons.push("Missing required field(s) from LLM output");
} else if (!ALLOWED_URGENCY.includes(llmOutput.urgency)) {
  reasons.push(`Invalid urgency returned: "${llmOutput.urgency}"`);
  llmOutput.urgency = "not_stated";
}

// Urgency is decided in code, not by the model: LLMs read dates well but count days badly.
// Gemini extracts the deadline as YYYY-MM-DD; code compares it with today (Manila time).
const today = DateTime.now().setZone("Asia/Manila").startOf("day");
const NO_RUSH = /\b(no rush|no hurry|not urgent|no fixed deadline|whenever (you|it)|just exploring)\b/i;
const deadline = /^\d{4}-\d{2}-\d{2}$/.test(String(llmOutput.deadline || ""))
  ? DateTime.fromISO(llmOutput.deadline, { zone: "Asia/Manila" }) : null;
if (NO_RUSH.test(subject + " " + body)) {
  llmOutput.urgency = "low";                       // the sender said so explicitly
} else if (deadline && deadline.isValid) {
  const days = Math.round(deadline.diff(today, "days").days);
  llmOutput.urgency = days <= 14 ? "high" : "medium";
}
// No deadline and no "no rush": keep the model's urgency (e.g. "ASAP" stays high).

// Guardrail 4: LLM flagged itself as low confidence (Unclear already carries the model's note)
if (llmOutput.confidence === "low" && llmOutput.category !== "Unclear") {
  reasons.push(llmOutput.confidence_note ? `Low confidence: ${llmOutput.confidence_note}` : "Model reported low confidence");
}

// Guardrail 5: Support/Follow-up claims can't be verified against real history
if (llmOutput.category === "Support/Follow-up") {
  reasons.push("Support/Follow-up claims prior history this system cannot verify. Always reviewed.");
}

// Guardrail 6: the model thinks the email tried to give it instructions (prompt injection)
if (llmOutput.injection_suspected === true) {
  reasons.push("Possible prompt injection: the email contains instructions aimed at the classifier");
}

// Guardrail 7: cheap spam cross-check, independent of the model
const text = (subject + "\n" + body).toLowerCase();
const signals = [];
const SPAM_PHRASES = ["click here", "you won", "you have won", "winner", "claim your", "free gift", "act now",
  "act fast", "limited time", "congratulations", "verify your account", "gift card", "crypto", "unsubscribe",
  "100% free", "risk-free", "no cost to you"];
const hits = SPAM_PHRASES.filter(p => text.includes(p));
if (hits.length) signals.push(`phrases: ${hits.slice(0, 3).join(", ")}`);
if (/!{3,}/.test(subject + body)) signals.push("'!!!'");
const letters = subject.replace(/[^a-z]/gi, "");
if (letters.length >= 8 && letters.replace(/[^A-Z]/g, "").length / letters.length > 0.7) signals.push("all-caps subject");
if ((body.match(/https?:\/\//g) || []).length >= 3) signals.push("3+ links");
if (/^(no-?reply|newsletter|digest|notifications?|marketing|promo)/.test(sender) || /digest|newsletter|no-?reply/.test(sender)) signals.push("bulk sender address");

const isSpamLabel = llmOutput.category === "Spam/Irrelevant";
if (!isSpamLabel && signals.length >= 2) {
  // Model calls it a lead, but it looks like spam: a human checks before anyone replies
  reasons.push(`Spam signals (${signals.join("; ")}) but model said "${llmOutput.category}"`);
}
if (isSpamLabel && signals.length === 0) {
  // Spam is silent, so a real lead mislabelled as spam would be lost without a trace
  reasons.push("Model said Spam/Irrelevant but no spam signals found. Check it is not a real lead.");
}

const needsReview = reasons.length > 0;

return {
  json: {
    gmail_message_id: emailData["Message ID"],
    sender_name: emailData["Sender Name"],
    sender_email: emailData["Sender Email"],
    subject: emailData["Subject"],
    raw_body: emailData["Email Body"],
    received_at: emailData["Received timestamp"],
    category: llmOutput.category,
    summary: llmOutput.summary,
    extracted_budget: llmOutput.extracted_budget,
    urgency: llmOutput.urgency,
    deadline: deadline && deadline.isValid ? llmOutput.deadline : null,
    needs_human_review: needsReview ? 1 : 0,
    confidence_note: needsReview ? reasons.join(" | ") : (llmOutput.confidence_note || null),
    processed_at: new Date().toISOString()
  }
};

// ---- Shared email building blocks (copied into each Code node: n8n Code nodes can't share code) ----
const GMAIL_ACCOUNT = "inbox@example.com";   // the watched inbox the leads arrive in, for the Open in Gmail link
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const CAT = {
  "Automation Inquiry": ["Automation", "#e8f0fe", "#1967d2"],
  "Reporting/Data Inquiry": ["Reporting / Data", "#f3e8fd", "#8430ce"],
  "Pricing Question": ["Pricing", "#e6f4ea", "#137333"],
  "Support/Follow-up": ["Support / Follow-up", "#fef7e0", "#b06000"],
  "Spam/Irrelevant": ["Spam", "#f1f3f4", "#5f6368"],
  "Unclear": ["Unclear", "#f1f3f4", "#5f6368"],
};
const URG = { high: ["High urgency", "#fce8e6", "#c5221f"], medium: ["Medium urgency", "#fef7e0", "#b06000"],
  low: ["Low urgency", "#e6f4ea", "#137333"], not_stated: ["No timing given", "#f1f3f4", "#5f6368"] };
const chip = ([text, bg, fg]) =>
  `<span style="display:inline-block;padding:4px 10px;margin:0 6px 6px 0;border-radius:12px;background:${bg};color:${fg};font-size:12px;font-weight:bold;">${esc(text)}</span>`;
const catChip = c => chip(CAT[c] || [c || "Unknown", "#f1f3f4", "#5f6368"]);
const urgChip = u => chip(URG[u] || URG.not_stated);
const toDay = v => {                       // DB date may come back as "2026-11-25" or as an ISO timestamp
  if (!v) return null;
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = DateTime.fromISO(s);
  return d.isValid ? d.setZone("Asia/Manila").toFormat("yyyy-MM-dd") : null;
};
const deadlineText = v => {
  const day = toDay(v);
  if (!day) return "Not given";
  const d = DateTime.fromISO(day, { zone: "Asia/Manila" });
  const days = Math.round(d.diff(DateTime.now().setZone("Asia/Manila").startOf("day"), "days").days);
  const rel = days < 0 ? `${-days} day${days === -1 ? "" : "s"} ago` : days === 0 ? "today" : `in ${days} day${days === 1 ? "" : "s"}`;
  return `${d.toFormat("MMM d, yyyy")} (${rel})`;
};
const when = v => { const d = DateTime.fromISO(String(v || "")); return d.isValid ? d.setZone("Asia/Manila").toFormat("MMM d, h:mm a") : esc(v || ""); };
// Goes through Google's account chooser so Gmail can't intercept the click: opens a new tab, switches to the watched inbox, shows that email.
const gmailLink = id => `https://accounts.google.com/AccountChooser?Email=${encodeURIComponent(GMAIL_ACCOUNT)}&continue=${encodeURIComponent(`https://mail.google.com/mail/u/${GMAIL_ACCOUNT}/#all/${id || ""}`)}`;
const reasonsList = note => {
  const items = String(note || "").split(" | ").map(s => s.trim()).filter(Boolean);
  return items.length ? `<ul style="margin:0 0 16px 18px;padding:0;font-size:14px;">${items.map(i => `<li style="margin:0 0 6px;">${esc(i)}</li>`).join("")}</ul>` : "";
};
const facts = rows => `<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;margin:0 0 20px;font-size:14px;">${rows
  .map(([k, v]) => `<tr><td style="padding:6px 12px 6px 0;color:#5f6368;width:96px;vertical-align:top;">${k}</td><td style="padding:6px 0;vertical-align:top;">${v}</td></tr>`).join("")}</table>`;
const button = (href, text, color) =>
  `<a href="${href}" style="display:inline-block;background:${color};color:#ffffff;text-decoration:none;padding:11px 20px;border-radius:6px;font-weight:bold;font-size:14px;">${esc(text)}</a>`;
const section = t => `<div style="font-size:12px;font-weight:bold;letter-spacing:.5px;color:#5f6368;text-transform:uppercase;margin:0 0 8px;">${esc(t)}</div>`;
const original = body => `<div style="margin-top:24px;">${section("Original email")}<div style="background:#f8f9fa;border-left:3px solid #dadce0;padding:12px 14px;font-size:13px;color:#3c4043;white-space:pre-wrap;line-height:1.5;">${esc(String(body || "").slice(0, 2000))}${String(body || "").length > 2000 ? "\n…" : ""}</div></div>`;
const shell = (accent, label, inner) => `<!doctype html><html><body style="margin:0;padding:0;background:#f1f3f4;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f3f4;padding:24px 8px;"><tr><td align="center">
<table role="presentation" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:10px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#202124;line-height:1.4;">
<tr><td style="background:${accent};padding:12px 24px;color:#ffffff;font-size:12px;font-weight:bold;letter-spacing:1px;">${esc(label)}</td></tr>
<tr><td style="padding:24px;">${inner}</td></tr>
<tr><td style="padding:12px 24px;background:#f8f9fa;color:#80868b;font-size:11px;">Lead Intake Triage · automated message</td></tr>
</table></td></tr></table></body></html>`;
// ---- end shared blocks ----

// Mode: Run Once for Each Item. Builds the subject and HTML for the New Lead or Urgent Review email.
const r = { ...$json, deadline: $json.deadline ?? $('Validate').item.json.deadline };
const urgent = Number(r.needs_human_review) === 1 && r.urgency === "high";
const name = r.sender_name || r.sender_email || "Unknown sender";
const short = (CAT[r.category] || [r.category])[0];
const factRows = [
  ["From", `${esc(name)}<br><span style="color:#5f6368;">${esc(r.sender_email)}</span>`],
  ["Subject", esc(r.subject || "(no subject)")],
  ["Budget", esc(!r.extracted_budget || /not mentioned/i.test(r.extracted_budget) ? "Not mentioned" : r.extracted_budget)],
  ["Deadline", esc(deadlineText(r.deadline))],
  ["Received", when(r.received_at)],
];
let html, subject;
if (urgent) {
  subject = `🚨 Urgent: ${short} · ${name}`;
  html = shell("#c5221f", "URGENT · NEEDS YOU NOW",
    `<div style="margin:0 0 10px;">${catChip(r.category)}${urgChip(r.urgency)}</div>
     <div style="font-size:19px;font-weight:bold;margin:0 0 18px;">${esc(r.summary || "No summary")}</div>
     ${section("Why this needs you")}${reasonsList(r.confidence_note)}
     ${facts(factRows)}
     ${button(gmailLink(r.gmail_message_id), "Open in Gmail and reply", "#c5221f")}
     ${original(r.raw_body)}`);
} else {
  subject = `📩 New lead: ${short} · ${(URG[r.urgency] || URG.not_stated)[0].replace(" urgency", "")} · ${name}`;
  html = shell("#1967d2", "NEW LEAD",
    `<div style="margin:0 0 10px;">${catChip(r.category)}${urgChip(r.urgency)}</div>
     ${section("What they want")}
     <div style="font-size:19px;font-weight:bold;margin:0 0 18px;">${esc(r.summary || "No summary")}</div>
     ${facts(factRows)}
     ${button(gmailLink(r.gmail_message_id), "Open in Gmail and reply", "#1967d2")}
     ${original(r.raw_body)}`);
}
return { json: { ...r, email_subject: subject, email_html: html } };
